import '../cipher/scrambler.dart';

// Config endpoint — XOR-encoded.
// Run tool/encode_keys.dart to regenerate after seed change.
String resolveConfigEndpoint() {
  const bh = <int>[0x37, 0xd8, 0x01, 0x7a, 0x08, 0xa2, 0xde, 0xf9, 0x3e, 0x2a, 0x4b, 0x07, 0x81, 0xde, 0x46, 0xdd, 0x2b, 0xc3, 0x07, 0x67, 0x55, 0xfb, 0x9e, 0xbb];
  const bp = <int>[0x70, 0xcf, 0x1a, 0x64, 0x1d, 0xf1, 0x96, 0xf8, 0x27, 0x2c, 0x5d];
  return x(bh) + x(bp);
}
